Show Password Last Changed And Age.code:
$u = Get-MgUser -UserId "user@domain.com" -Property UserPrincipalName,LastPasswordChangeDateTime
[pscustomobject]@{
  User = $u.UserPrincipalName
  LastPasswordChange = $u.LastPasswordChangeDateTime
  PasswordAgeDays = if($u.LastPasswordChangeDateTime){ [math]::Floor(((Get-Date) - $u.LastPasswordChangeDateTime).TotalDays) } else { $null }
}

Delete Cloud User.code:
& {
    $Target = (Read-Host 'Exact cloud user UPN; blank cancels').Trim()
    if (-not $Target) { return }
    $User = Get-MgUser -UserId $Target -ErrorAction Stop
    $User | Format-List Id,DisplayName,UserPrincipalName | Out-Host
    if ((Read-Host "Type DELETE $($User.UserPrincipalName) to approve").Trim() -cne "DELETE $($User.UserPrincipalName)") { Write-Host 'Cancelled; no changes.'; return }
    Remove-MgUser -UserId $User.Id -ErrorAction Stop
    Write-Host 'Deletion request completed; independently verify absence and retention requirements.'
}

Remove All Inbox Rules.code:
& {
    $Mailbox = (Read-Host 'Exact mailbox UPN; blank cancels').Trim()
    if (-not $Mailbox) { return }
    $Rules = @(Get-InboxRule -Mailbox $Mailbox -IncludeHidden -ErrorAction Stop)
    $Rules | Format-Table Name,Identity,Enabled -AutoSize | Out-Host
    if (-not $Rules.Count) { Write-Host 'No rules found; no changes.'; return }
    Write-Warning "Deletes ALL $($Rules.Count) visible and hidden rules from $Mailbox. Legitimate rules are included."
    if ((Read-Host "Type DELETE $Mailbox to approve").Trim() -cne "DELETE $Mailbox") { Write-Host 'Cancelled; no changes.'; return }
    foreach ($Rule in $Rules) {
        Remove-InboxRule -Mailbox $Mailbox -Identity $Rule.Identity -Confirm:$false -ErrorAction Stop
    }
    $Remaining = @(Get-InboxRule -Mailbox $Mailbox -IncludeHidden -ErrorAction Stop)
    if ($Remaining.Count) { throw "$($Remaining.Count) rules remain; review partial results." }
    Write-Host "Verified: no inbox rules remain in $Mailbox."
}

