Hard-Delete Search Results.code:
& {
    $SearchName = (Read-Host 'Exact completed compliance search name; blank cancels').Trim()
    if (-not $SearchName) { return }
    $Search = Get-ComplianceSearch -Identity $SearchName -ErrorAction Stop
    $Search | Format-List Name,Status,Items,Size,ExchangeLocation,ContentMatchQuery | Out-Host
    if ($Search.Status -ne 'Completed') { throw 'Search must be completed before purge.' }
    Write-Warning 'Hard-delete the matching search results. Confirm the query and mailbox scope above.'
    if ((Read-Host "Type PURGE $SearchName to approve").Trim() -cne "PURGE $SearchName") { Write-Host 'Cancelled; no changes.'; return }
    New-ComplianceSearchAction -SearchName $SearchName -Purge -PurgeType HardDelete -ErrorAction Stop
    Write-Host 'Purge submitted; check compliance action status and service purge limits before claiming completion.'
}

